<script setup lang="ts">import{onMounted,onBeforeUnmount,ref,watch}from'vue';import{ZoomIn,ZoomOut}from'lucide-vue-next';const props=defineProps<{file:File}>();const host=ref<HTMLDivElement|null>(null),loading=ref(true),error=ref(''),zoom=ref(1);let osmd:any=null;async function render(){if(!host.value)return;loading.value=true;error.value='';try{const{OpenSheetMusicDisplay}=await import('opensheetmusicdisplay');if(!osmd)osmd=new OpenSheetMusicDisplay(host.value,{autoResize:true,backend:'svg',drawTitle:true,followCursor:false});await osmd.load(await props.file.text());osmd.Zoom=zoom.value;osmd.render()}catch(e){error.value=e instanceof Error?e.message:'No se pudo abrir la partitura MusicXML.'}finally{loading.value=false}}function setZoom(n:number){zoom.value=Math.max(.5,Math.min(2,zoom.value+n));if(osmd){osmd.Zoom=zoom.value;osmd.render()}}onMounted(render);watch(()=>props.file,render);onBeforeUnmount(()=>{if(host.value)host.value.innerHTML=''})</script><template><div><div class="mb-3 flex items-center justify-between gap-2"><p class="text-sm font-bold text-[#52685c]">{{file.name}}</p><div class="flex items-center gap-2"><button class="secondary" aria-label="Alejar" @click="setZoom(-.1)"><ZoomOut :size="17"/></button><span class="text-xs font-bold">{{Math.round(zoom*100)}}%</span><button class="secondary" aria-label="Acercar" @click="setZoom(.1)"><ZoomIn :size="17"/></button></div></div><p v-if="loading" class="py-8 text-center text-sm text-[#788780]">Cargando partitura…</p><p v-if="error" class="rounded-xl bg-red-50 p-4 text-sm text-red-700">{{error}}</p><div ref="host" class="max-w-full overflow-x-auto"/></div></template>